import { cookies, headers } from 'next/headers';

export default async function ThemePreferences() {
  const cookieStore = await cookies();
  const headerStore = await headers();

  const theme = cookieStore.get('theme')?.value ?? 'light';
  const acceptLanguage = headerStore.get('accept-language') ?? '';

  // Parse preferred language from Accept-Language header (e.g., "en-US,en;q=0.9,es;q=0.8" -> "en-US")
  const preferredLanguage = acceptLanguage
    ? acceptLanguage.split(',')[0].trim().split('-')[0]
    : 'unknown';

  return (
    <section aria-label="User preferences">
      <div>
        <strong>Theme:</strong> {theme}
      </div>
      <div>
        <strong>Preferred Language:</strong> {preferredLanguage}
      </div>
    </section>
  );
}

